<?php
namespace App\Http\Controllers;use App\Http\Requests\{StoreTransportCalendarExceptionRequest,StoreTransportScheduleRequest};use App\Models\{TransportCalendarException,TransportPerson,TransportRoute,TransportSchedule,TransportVehicle};use App\Services\{TransportAuditService,TransportScheduleGeneratorService};use Illuminate\Http\Request;use Illuminate\Support\Facades\DB;
class TransportScheduleController extends Controller{public function index(){return view('transport.schedules.index',$this->data());}public function store(StoreTransportScheduleRequest$r,TransportAuditService$audit){$d=$r->validated();$s=DB::transaction(function()use($d,$r,$audit){$s=TransportSchedule::create(collect($d)->except('weekdays')->all()+['company_id'=>$r->user()->company_id,'status'=>'active','created_by'=>$r->user()->id]);$s->days()->createMany(array_map(fn($day)=>['day_of_week'=>$day],$d['weekdays']));$audit->record($s->company_id,'transport_schedule_created','schedule',$s->id,$r->user()->id);return$s;});return redirect()->route('transport.schedules.preview',$s)->with('success','Programación creada. Revise la previsualización antes de generar.');}public function preview(TransportSchedule$schedule,TransportScheduleGeneratorService$generator){$this->own($schedule);$schedule->load(['route','days','vehicle','driver.employee','monitor.employee']);return view('transport.schedules.preview',['schedule'=>$schedule,'preview'=>$generator->preview($schedule)]);}public function generate(TransportSchedule$schedule,TransportScheduleGeneratorService$generator){$this->own($schedule);$count=$generator->generate($schedule,auth()->id());return redirect()->route('transport.operation.index')->with('success',"Se generaron {$count} servicios; los existentes no se duplicaron.");}public function exception(StoreTransportCalendarExceptionRequest$r,TransportAuditService$audit){$d=$r->validated();if($d['applies_to_all_routes'])$d['transport_route_id']=null;$e=TransportCalendarException::create($d+['company_id'=>$r->user()->company_id,'created_by'=>$r->user()->id]);$audit->record($e->company_id,'transport_calendar_exception_created','calendar_exception',$e->id,$r->user()->id);return back()->with('success','Excepción de calendario registrada.');}private function data():array{$c=auth()->user()->company_id;return['schedules'=>TransportSchedule::forCompany($c)->with(['route','days'])->latest()->paginate(15),'exceptions'=>TransportCalendarException::forCompany($c)->with('route')->latest('exception_date')->limit(30)->get(),'routes'=>TransportRoute::forCompany($c)->where('status','active')->orderBy('name')->get(),'vehicles'=>TransportVehicle::forCompany($c)->where('status','active')->get(),'drivers'=>TransportPerson::forCompany($c)->with('employee')->where('status','active')->where('is_driver',1)->get(),'monitors'=>TransportPerson::forCompany($c)->with('employee')->where('status','active')->where('is_monitor',1)->get()];}private function own($m):void{abort_unless((int)$m->company_id===(int)auth()->user()->company_id,404);}}
